import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DIGITS = "0123456789"


def _normalize_email(raw):
    value = raw.strip()
    match = re.search(r"<([^<>]*)>", value)
    if match:
        value = match.group(1)
    value = value.strip().lower()
    if value.count("@") == 1:
        local, domain = value.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            value = f"{local}@gmail.com"
    return value


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    value = raw.lower()
    cut = len(value)
    for marker in ("x", "ext", "#"):
        idx = value.find(marker)
        if idx != -1:
            cut = min(cut, idx)
    digits = "".join(ch for ch in value[:cut] if ch in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    value = raw.strip()
    match = re.fullmatch(r"([0-9]+)-[0-9]{4}", value)
    if match:
        value = match.group(1)
    if len(value) == 4 and all(ch in _DIGITS for ch in value):
        value = "0" + value
    if len(value) == 5 and all(ch in _DIGITS for ch in value):
        return value
    return ""


def _normalize_name(raw):
    value = raw.strip()
    if value.isupper() or value.islower():
        value = value.title()
    return value


def _parse_updated(raw):
    value = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    return None  # unparseable: treated as older than any dated row


def _is_opted_out(raw):
    return raw.strip().lower() in _OPT_OUT_VALUES


def _normalize_tags(raw):
    tags = set()
    for part in re.split(r"[;,]", raw):
        tag = part.strip().lower()
        if tag:
            tags.add(tag)
    return tags


def _preference(rec):
    # Lower sorts first: manual sources, then most recent updated, then earliest input row.
    ts = rec["updated"] if rec["updated"] is not None else datetime.min
    return (not rec["manual"], -(ts - datetime.min), rec["idx"])


def _merge_group(members):
    def pick(field):
        candidates = [m for m in members if m[field]]
        if not candidates:
            return ""
        return min(candidates, key=_preference)[field]

    dates = [m["updated"] for m in members if m["updated"] is not None]
    all_tags = set()
    for m in members:
        all_tags |= m["tags"]

    return {
        "first_name": pick("first_name"),
        "last_name": pick("last_name"),
        "zip": pick("zip"),
        "email": pick("email"),
        "phone": pick("phone"),
        "source": pick("source"),
        "tags": ";".join(sorted(all_tags)),
        "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
        "updated": max(dates).strftime("%Y-%m-%d") if dates else "",
    }


def dedupe_contacts(rows):
    # Step 1: normalize each row; drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row["email"])
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row["phone"])
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        source = row["source"].strip().lower()
        records.append({
            "idx": idx,
            "first_name": _normalize_name(row["first_name"]),
            "last_name": _normalize_name(row["last_name"]),
            "zip": _normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "updated": _parse_updated(row["updated"]),
            "tags": _normalize_tags(row["tags"]),
            "opted_out": _is_opted_out(row["opted_out"]),
        })

    # Step 2: union-find over records that share a valid email,
    # or a valid phone plus the same non-empty last name.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for pos, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(first_by_email[rec["email"]], pos)
            else:
                first_by_email[rec["email"]] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].lower())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], pos)
            else:
                first_by_phone_last[key] = pos

    # Step 3: collect groups. Dict insertion order follows each group's
    # earliest input row, and members stay in input order.
    groups = {}
    for pos, rec in enumerate(records):
        groups.setdefault(find(pos), []).append(rec)

    # Step 4: merge each group into one output dict.
    return [_merge_group(members) for members in groups.values()]
```

Notes for the send step:

- Filter out `opted_out == "Y"` before the action alert goes out. Because groups are merged, one opted-out row suppresses the whole person, including their duplicate rows.
- The function assumes every row has all nine keys, as your data person described. If a key is missing, you'll get a KeyError.
- An unparseable `updated` value is ranked as oldest rather than raising an error. If you'd rather catch bad dates, change `_parse_updated` to raise.
